import { setPathValue } from './form-utils.js';
import { validatorFor, enumOptions } from './field-utils.js';

// knownDefaults (catalog.deviceFieldDefaults[objectId], from data/catalog/deviceFieldDefaults.json,
// generated by pak-server's CatalogExtractor.LoadDeviceFieldDefaults from device-field-defaults.json)
// holds verified native defaults for specific fields - discovered by placing the device with the field
// left unset, saving, loading in-game, then diffing what the game's own re-save backfilled it to (see
// pugc_HeaderTest/ for the round-trip that found the vehicle ones). Checked first, before any
// type-based guessing below, since these are confirmed values, not best-effort fallbacks - e.g.
// bAutoRespawnVehicle defaults to false in-game, not true like you might expect, and not every Bool
// field's blanket false either. If pak-server ever gains a real way to dump these (a proper CDO/
// native-default reader), that just replaces device-field-defaults.json - this already prefers
// whatever's there over its own guessing, no code changes needed here.
export function defaultDeviceFieldValue(field, enums, stringTables, knownDefaults) {
  if (knownDefaults && knownDefaults[field.path] !== undefined) return knownDefaults[field.path];
  const v = validatorFor(field);
  if (field.type === 'Bool') return false;
  if (field.type === 'Int' || field.type === 'Float') return Number(v.minValue ?? 0);
  if (field.type === 'Enum') {
    if (field.path === 'activationRoundPhase') return 'DeviceCreation';
    if (v.valueSet?.[0]) return v.valueSet[0];
    const first = enumOptions(field, enums)[0];
    return first?.value ?? '';
  }
  if (field.type === 'String') {
    const tableName = v.stringDataTable;
    // bAllowEmpty: true means '' is a legitimate, intentional value (the UI offers an explicit
    // "(None)" option for it) - only force a real selection when '' would violate the field's own
    // validator, which is the actual bug this guards against (see knownDefaults above).
    if (tableName && tableName !== 'None' && v.bAllowEmpty !== true) {
      // Fallback: the first table row is at least a valid, non-empty value, even if not confirmed to
      // match the game's real default (see the comment on knownDefaults above).
      const rows = stringTables?.[tableName];
      if (Array.isArray(rows) && rows.length) return String(rows[0].value ?? rows[0].asset ?? '');
    }
    return '';
  }
  if (field.type === 'Item') return { itemId: 'None', itemCount: 1 };
  if (field.type === 'Array') return [];
  if (field.type === 'Vector') return v.minVector || { x: 0, y: 0, z: 0 };
  return '';
}

export function defaultDeviceProperties(deviceEntry, enums, stringTables, knownDefaults) {
  const props = {};
  for (const field of deviceEntry?.fields || []) {
    if (!field.path || field.type === 'Object' || field.path.includes('[].') || field.path.endsWith('[]')) continue;
    setPathValue(props, field.path, defaultDeviceFieldValue(field, enums, stringTables, knownDefaults));
  }
  return props;
}
